}, {\"bbox\": [{\"coord\": [636, 97, 994, 125], \"page_id\": 119}], \"content\": \"RESEARCH PAPER SERIES\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1443, 97, 1488, 125], \"page_id\": 119}], \"content\": \"115\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [142, 193, 1424, 255], \"page_id\": 119}], \"content\": \"2003-01. \\u201cAnnuity Risk: Volatility and Inflation Exposure in Payments from Immediate Life Annuities.\\u201d Christopher J. Soares and Mark Warshawsky. January 2003.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 280, 1475, 342], \"page_id\": 119}], \"content\": \"2005-01. \\u201cPossible Alternatives to the Medicare Trustees\\u2019 Long-Term Projections of Health Spending.\\u201d Jason D. Brown and Ralph M. Monaco. January 2005.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 370, 1182, 401], \"page_id\": 119}], \"content\": \"2005-02. \\\"The Long-Term Real Interest Rate for Social Security.\\\" James A. Girola. March 2005.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 427, 1455, 488], \"page_id\": 119}], \"content\": \"2006-01. \\u201cImplications of Returns on Treasury Inflation-Indexed Securities for Projections of the Long-Term Real Interest Rate.\\u201d James A. Girola. March 2006.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 514, 1488, 575], \"page_id\": 119}], \"content\": \"2007-01. \\u201cMortality and Lifetime Income Evidence from Social Security Records.\\u201d James E. Duggan, Robert Gillingham, and John S. Greenlees. December 2006.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 603, 1410, 662], \"page_id\": 119}], \"content\": \"2007-02. \\u201cThe Impact of Post-9/11 Visa Policies on Travel to the United States.\\u201d Brent Neiman and Phillip L. Swagel. June 2007.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [570, 1690, 1058, 1827], \"page_id\": 119}], \"content\": \"Copies may be obtained by writing to: Ann Bailey, Department of the Treasury 1500 Pennsylvania Ave., NW., Room 4409 MT Washington, DC 20220 Telephone (202) 622-1519 or fax (202) 622-4112\", \"description\": null, \"id\": 8, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [1335, 1992, 1488, 2018], \"page_id\": 119}], \"content\": \"December 2008\", \"description\": null, \"id\": 9, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [138, 92, 197, 132], \"page_id\": 120}], \"content\": \"116\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [421, 212, 1208, 302], \"page_id\": 120}], \"content\": \"Glossary With References to Applicable Sections and Tables\", \"description\": null, \"id\": 1, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [596, 316, 1035, 361], \"page_id\": 120}], \"content\": \"Source: Financial Management Service\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [129, 391, 800, 554], \"page_id\": 120}], \"content\": \"Amounts outstanding and in circulation (USCC)\\u2014Includes all issues by the Bureau of the Mint purposely intended as a medium of exchange. Coins sold by the Bureau of the Mint at premium prices are excluded; however, uncirculated coin sets sold at face value plus handling charge are included.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 563, 801, 691], \"page_id\": 120}], \"content\": \"Average discount rate (PDO-1, -2)\\u2014In Treasury bill auctions, purchasers tender competitive bids on a discount rate basis. The average discount rate is the weighted, or adjusted, average of all bids accepted in the auction.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 702, 807, 922], \"page_id\": 120}], \"content\": \"Budget authority (\\u201cFederal Fiscal Operations\\u201d)\\u2014Congress passes laws giving budget authority to Government entities, which gives the agencies the power to spend Federal funds. Congress can stipulate various criteria for the spending of these funds. For example, Congress can stipulate that a given agency must spend within a specific year, number of years, or any time in the future.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 936, 809, 1247], \"page_id\": 120}], \"content\": \"The basic forms of budget authority are appropriations, authority to borrow, contract authority, and authority to obligate and expend offsetting receipts and collections. The period of time during which Congress makes funds available may be specified as 1-year, multiple-year, or no-year. The available amount may be classified as either definite or indefinite; a specific amount or an unspecified amount can be made available. Authority also may be classified as current or permanent. Permanent authority requires no current action by Congress.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 1256, 800, 1322], \"page_id\": 120}], \"content\": \"Budget deficit\\u2014The total, cumulative amount by which budget outlays (spending) exceed budget receipts (income).\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 1329, 803, 1492], \"page_id\": 120}], \"content\": \"Cash management bills (PDO-1)\\u2014Marketable Treasury bills of irregular maturity lengths, sold periodically to fund short-term cash needs of Treasury. Their sale, having higher minimum and multiple purchase requirements than those of other issues, is generally restricted to competitive bidders.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1502, 803, 1657], \"page_id\": 120}], \"content\": \"Competitive tenders (\\\"Treasury Financing Operations\\\")\\u2014A bid to purchase a stated amount of one issue of Treasury securities at a specified yield or discount. The bid is accepted if it is within the range accepted in the auction. (See Noncompetitive tenders.)\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1671, 798, 1766], \"page_id\": 120}], \"content\": \"Currency no longer issued (USCC)\\u2014Old and new series gold and silver certificates, Federal Reserve notes, national bank notes, and 1890 Series Treasury notes.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 1780, 803, 1909], \"page_id\": 120}], \"content\": \"Debt outstanding subject to limitation (FD-6)\\u2014The debt incurred by the Treasury subject to the statutory limit set by Congress. Until World War I, a specific amount of debt was authorized to each separate security issue. Beginning with the\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [821, 396, 1494, 552], \"page_id\": 120}], \"content\": \"Second Liberty Loan Act of 1917, the nature of the limitation was modified until, in 1941, it developed into an overall limit on the outstanding Federal debt. As of September 2008, the debt limit was $10,615,000 million; the limit may change from year to year.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [823, 563, 1495, 726], \"page_id\": 120}], \"content\": \"The debt subject to limitation includes most of Treasury's public debt except securities issued to the Federal Financing Bank, upon which there is a limitation of $15 billion, and certain categories of older debt (totaling approximately $595 million as of February 1991).\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [825, 733, 1492, 801], \"page_id\": 120}], \"content\": \"Discount\\u2014The interest deducted in advance when purchasing notes or bonds. (See Accrued discount.)\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [823, 811, 1494, 969], \"page_id\": 120}], \"content\": \"Discount rate (PDO-1)\\u2014The difference between par value and the actual purchase price paid, annualized over a 360-day year. Because this rate is less than the actual yield (coupon-equivalent rate), the yield should be used in any comparison with coupon issue securities.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [825, 978, 1490, 1042], \"page_id\": 120}], \"content\": \"Dollar coins (USCC)\\u2014Include standard silver and nonsilver coins.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [823, 1051, 1494, 1216], \"page_id\": 120}], \"content\": \"Domestic series (FD-2)\\u2014Nonmarketable, interest- and non-interest-bearing securities issued periodically by Treasury to the Resolution Funding Corporation (RFC) for investment of funds authorized under section 21B of the Federal Home Loan Bank Act (12 United States Code 1441b).\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 1223, 1499, 1355], \"page_id\": 120}], \"content\": \"Federal intrafund transactions (\\\"Federal Fiscal Operations\\\")\\u2014Intrabudgetary transactions in which payments and receipts both occur within the same Federal fund group (Federal funds or trust funds).\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 1365, 1499, 1584], \"page_id\": 120}], \"content\": \"Federal Reserve notes (USCC)\\u2014Issues by the U.S. Government to the public through the Federal Reserve banks and their member banks. They represent money owed by the Government to the public. Currently, the item \\u201cFederal Reserve notes\\u2014amounts outstanding\\u201d consists of new series issues. The Federal Reserve note is the only class of currency currently issued.\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [827, 1593, 1497, 1692], \"page_id\": 120}], \"content\": \"Foreign (\\u201cForeign Currency Positions,\\u201d IFS-2, -3)\\u2014Locations other than those included under the definition of the United States. (See United States.)\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 1702, 1495, 1890], \"page_id\": 120}], \"content\": \"Foreigner (\\u201cCapital Movements,\\u201d IFS-2)\\u2014All institutions and individuals living outside the United States, including U.S. citizens living abroad, and branches, subsidiaries, and other affiliates abroad of U.S. banks and business concerns; central governments, central banks, and other official institutions of countries other than the United States; and\", \"description\": null, \"id\": 21, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 1989, 299, 2020], \"page_id\": 120}], \"content\": \"December 2008\", \"description\": null, \"id\": 22, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [740, 97, 891, 127], \"page_id\": 121}], \"content\": \"GLOSSARY\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1443, 97, 1494, 127], \"page_id\": 121}], \"content\": \"117\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [138, 191, 800, 316], \"page_id\": 121}], \"content\": \"international and regional organizations, wherever located. Also refers to persons in the United States to the extent that they are known by reporting institutions to be acting for foreigners.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 332, 800, 639], \"page_id\": 121}], \"content\": \"Foreign official institutions (\\\"Capital Movements\\\")\\u2014Includes central governments of foreign countries, including all departments and agencies of national governments; central banks, exchange authorities, and all fiscal agents of foreign national governments that undertake activities similar to those of a treasury, central bank, or stabilization fund; diplomatic and consular establishments of foreign national governments; and any international or regional organization, including subordinate and affiliate agencies, created by treaty or convention between sovereign states.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 653, 800, 872], \"page_id\": 121}], \"content\": \"Foreign public borrower (\\u201cCapital Movements\\u201d)\\u2014Includes foreign official institutions, as defined above, the corporations and agencies of foreign central governments, including development banks and institutions, and other agencies that are majority-owned by the central government or its departments; and state provincial and local governments of foreign countries and their departments and agencies.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 884, 800, 1131], \"page_id\": 121}], \"content\": \"Foreign-targeted issue (PDO-2)\\u2014Foreign-targeted issues were notes sold between October 1984 and February 1986 to foreign institutions, foreign branches of U.S. institutions, foreign central banks or monetary authorities, or to international organizations in which the United States held membership. Sold as companion issues, they could be converted to domestic (normal) Treasury notes with the same maturity and interest rates. Interest was paid annually.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1143, 798, 1207], \"page_id\": 121}], \"content\": \"Fractional coins (USCC)\\u2014Coins minted in denominations of 50, 25, and 10 cents, and minor coins (5 cents and 1 cent).\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1221, 800, 1593], \"page_id\": 121}], \"content\": \"Government account series (FD-2)\\u2014Certain trust fund statutes require the Secretary of the Treasury to apply monies held by these funds toward the issuance of nonmarketable special securities. These securities are sold directly by Treasury to a specific Government agency, trust fund, or account. Their rate is based on an average of market yields on outstanding Treasury obligations, and they may be redeemed at the option of the holder. Roughly 80 percent of these are issued to five holders: the Federal Old-Age and Survivors Insurance Trust Fund; the civil service retirement and disability fund; the Federal Hospital Insurance Trust Fund; the military retirement fund; and the Unemployment Trust Fund.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 1605, 800, 1730], \"page_id\": 121}], \"content\": \"Interfund transactions (\\\"Federal Fiscal Operations\\\")\\u2014Transactions in which payments are made from one fund group (either Federal funds or trust funds) to a receipt account in another group.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1747, 800, 1900], \"page_id\": 121}], \"content\": \"International Monetary Fund (\\\"Exchange Stabilization Fund,\\\" IFS-1)\\u2014(IMF) Established by the United Nations, the IMF promotes international trade, stability of exchange, and monetary cooperation. Members are allowed to draw from the fund.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 193, 1488, 346], \"page_id\": 121}], \"content\": \"Intrabudgetary transactions (\\\"Federal Fiscal Operations\\\")\\u2014These occur when payment and receipt both occur within the budget, or when payment is made from off-budget Federal entities whose budget authority and outlays are excluded from the budget totals.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 363, 1490, 486], \"page_id\": 121}], \"content\": \"Noncompetitive tenders (\\\"Treasury Financing Operations\\\")\\u2014This is a tender or bid to purchase a stated par amount of securities at the highest yield or discount rate awarded to competitive bidders for a single-price auction.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 500, 1490, 566], \"page_id\": 121}], \"content\": \"Obligations (\\u201cFederal Fiscal Operations\\u201d)\\u2014An unpaid commitment to acquire goods or services.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 578, 1490, 764], \"page_id\": 121}], \"content\": \"Off-budget Federal entities (\\u201cFederal Fiscal Operations\\u201d)\\u2014 Federally owned and controlled entities whose transactions are excluded from the budget totals under provisions of law. Their receipts, outlays, and surplus or deficit are not included in budget receipts, outlays, or deficits. Their budget authority is not included in totals of the budget.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 776, 1492, 872], \"page_id\": 121}], \"content\": \"Outlays (\\u201cFederal Fiscal Operations\\u201d)\\u2014Payments on obligations in the form of cash, checks, the issuance of bonds or notes, or the maturing of interest coupons.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 884, 1492, 1009], \"page_id\": 121}], \"content\": \"Own foreign offices (\\u201cCapital Movements\\u201d)\\u2014Refers to U.S. reporting institutions' parent organizations, branches and/or majority-owned subsidiaries located outside the United States.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 1023, 1492, 1089], \"page_id\": 121}], \"content\": \"Par value\\u2014The face value of bonds or notes, including interest.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 1101, 1492, 1351], \"page_id\": 121}], \"content\": \"Quarterly financing (\\u201cTreasury Financing Operations\\u201d)\\u2014Treasury has historically offered packages of several \\u201ccoupon\\u201d security issues on the 15th of February, May, August, and November, or on the next working day. These issues currently consist of a 3-year note, a 10-year note, and a 30-year bond. Treasury sometimes offers additional amounts of outstanding long-term notes or bonds, rather than selling new security issues. (See Reopening.)\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 1362, 1490, 1487], \"page_id\": 121}], \"content\": \"Receipts (\\\"Federal Fiscal Operations\\\")\\u2014Funds collected from selling land, capital, or services, as well as collections from the public (budget receipts), such as taxes, fines, duties, and fees.\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 1499, 1490, 1626], \"page_id\": 121}], \"content\": \"Reopening (PDO-2)\\u2014The offer for sale of additional amounts of outstanding issues, rather than an entirely new issue. A reopened issue will always have the same maturity date, CUSIP-number, and interest rate as the original issue.\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 1638, 1492, 1794], \"page_id\": 121}], \"content\": \"Special drawing rights (\\u201cExchange Stabilization Fund,\\u201d IFS-1)\\u2014International assets created by IMF that serve to increase international liquidity and provide additional international reserves. SDRs may be purchased and sold among eligible holders through IMF. (See IMF.)\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 1808, 1492, 1902], \"page_id\": 121}], \"content\": \"SDR allocations are the counterpart to SDRs issued by IMF based on members' quotas in IMF. Although shown in Exchange Stabilization Fund (ESF) statements as liabilities,\", \"description\": null, \"id\": 21, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1335, 1989, 1494, 2020], \"page_id\": 121}], \"content\": \"December 2008\", \"description\": null, \"id\": 22, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [144, 97, 195, 125], \"page_id\": 122}], \"content\": \"118\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [740, 97, 894, 127], \"page_id\": 122}], \"content\": \"GLOSSARY\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [142, 193, 800, 288], \"page_id\": 122}], \"content\": \"they must be redeemed by ESF only in the event of liquidation of, or U.S. withdrawal from, the SDR department of IMF or cancellation of SDRs.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 299, 800, 424], \"page_id\": 122}], \"content\": \"SDR certificates are issued to the Federal Reserve System against SDRs when SDRs are legalized as money. Proceeds of monetization are deposited into an ESF account at the Federal Reserve Bank of New York.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 438, 800, 504], \"page_id\": 122}], \"content\": \"Spot (\\u201cForeign Currency Positions\\u201d)\\u2014Due for receipt or delivery within 2 workdays.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 516, 801, 825], \"page_id\": 122}], \"content\": \"State and local government series (SLGS) (FD-2)\\u2014Special nonmarketable certificates, notes, and bonds offered to State and local governments as a means to invest proceeds from their own tax-exempt financing. Interest rates and maturities comply with IRS arbitrage provisions. SLGS are offered in both time deposit and demand deposit forms. Time deposit certificates have maturities of up to 1 year. Notes mature in 1 to 10 years and bonds mature in more than 10 years. Demand deposit securities are 1-day certificates rolled over with a rate adjustment daily.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 839, 800, 966], \"page_id\": 122}], \"content\": \"Statutory debt limit (FD-6)\\u2014By Act of Congress there is a limit, either temporary or permanent, on the amount of public debt that may be outstanding. When this limit is reached, Treasury may not sell new debt issues until Congress\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 191, 1490, 290], \"page_id\": 122}], \"content\": \"increases or extends the limit. For a detailed listing of changes in the limit since 1941, see the Budget of the United States Government. (See debt outstanding subject to limitation.)\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 299, 1494, 516], \"page_id\": 122}], \"content\": \"STRIPS (PDO-2)\\u2014Separate Trading of Registered Interest and Principal Securities. Long-term notes and bonds may be divided into principal and interest-paying components, which may be transferred and sold in amounts as small as $1,000. STRIPS are sold at auction at a minimum par amount, varying for each issue. The amount is an arithmetic function of the issue\\u2019s interest rate.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 528, 1494, 625], \"page_id\": 122}], \"content\": \"Treasury bills\\u2014The shortest term Federal security (maturity dates normally varying from 3 to 12 months), are sold at a discount.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 636, 1495, 733], \"page_id\": 122}], \"content\": \"Trust fund transaction (\\u201cFederal Fiscal Operations\\u201d)\\u2014An intrabudgetary transaction in which both payments and receipts occur within the same trust fund group.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 747, 1490, 870], \"page_id\": 122}], \"content\": \"United States\\u2014Includes the 50 States, District of Columbia, Commonwealth of Puerto Rico, American Samoa, Midway Island, Virgin Islands, Wake Island, and all other territories and possessions.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 884, 1490, 981], \"page_id\": 122}], \"content\": \"U.S. notes (USCC)\\u2014Legal tender notes of five different issues: 1862 ($5-$1,000 notes); 1862 ($1-$2 notes); 1863 ($5-$1,000 notes); 1863 ($1-$10,000 notes); and 1901 ($10 notes).\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1989, 302, 2018], \"page_id\": 122}], \"content\": \"December 2008\", \"description\": null, \"id\": 13, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [82, 82, 357, 191], \"page_id\": 123}], \"content\": null, \"description\": null, \"id\": 0, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [368, 92, 678, 196], \"page_id\": 123}], \"content\": \"U.S. GOVERNMENT PRINTING OFFICE KEEPING AMERICA INFORMED\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [709, 80, 1546, 189], \"page_id\": 123}], \"content\": \"PUBLICATION AND SUBSCRIPTION ORDER FORM\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [91, 214, 350, 250], \"page_id\": 123}], \"content\": \"Order Processing Code: 3509\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [381, 219, 672, 273], \"page_id\": 123}], \"content\": \"Easy Secure Internet bookstore.gpo.gov\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [849, 219, 1082, 295], \"page_id\": 123}], \"content\": \"Toll Free: 866 512-1800\\nDC Area: 202 512-1800\\nFax: 202 512-2104\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1242, 212, 1543, 290], \"page_id\": 123}], \"content\": \"Mail: U.S. Government Printing Office PO Box 979050 St. Louis, MO 63197\\u20139000\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [93, 271, 264, 304], \"page_id\": 123}], \"content\": \"Publications\", \"description\": null, \"id\": 7, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [82, 309, 1541, 849], \"pag